if isClient then
    TriggerGiftDataMgr = Plugins.Require("trigger_gift", "client.data.TriggerGiftDataMgr")
    Plugins.Require("trigger_gift", "client.packet.PacketHandler")
else
    TriggerGiftMgr = Plugins.Require("trigger_gift", "server.controller.TriggerGiftMgr")
    Plugins.Require("trigger_gift", "server.packet.PacketHandler")
end

---@param player GamePlayer
function handlers.onPlayerReady(player)
    if isClient then
        return
    end
    player.triggerGiftMgr = TriggerGiftMgr.new(player)
end

function handlers.onPlayerLogout(player)
    if isClient then
        return
    end
    if player.triggerGiftMgr then
        player.triggerGiftMgr:destroy()
        player.triggerGiftMgr = nil
    end
end

---@param player GamePlayer
function handlers.onSavePlayerDBData(player, immediate)
    if not player.triggerGiftMgr then
        return
    end
    player.triggerGiftMgr:onSavePlayerDBData(immediate)
end

---@param player GamePlayer
---@param key string
---@param value number
function handlers.onPlayerDataChange(player, key, ...)
    if not player.triggerGiftMgr then
        return
    end
    if GameConfig and GameConfig.enableTriggerGiftMgr then
        player.triggerGiftMgr:onPlayerDataChange(key, ...)
    end
end

---@param player GamePlayer
---@param rechargePoints number
function handlers.setRechargePoints(player, rechargePoints)
    if not player.triggerGiftMgr then
        return
    end
    player.triggerGiftMgr:setCurRechargePoints(rechargePoints)
end

